#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int P;
    cin >> P;

    while (P--) {
        ll L, A, B;
        cin >> L >> A >> B;

        ll N = B - A + 1;

        // Find maximum m such that sum of m smallest values from [A, B] is < L
        ll lo = 0, hi = 5000000;
        while (lo < hi) {
            ll mid = (lo + hi + 1) / 2;
            ll sum = mid * A + mid * (mid - 1) / 2;
            if (sum < L)
                lo = mid;
            else
                hi = mid - 1;
        }

        ll ans = min(N, lo + 1);
        cout << ans << '\n';
    }

    return 0;
}
